/// <summary>
/// The answer of HSMobileOpsSkuPageService::getSkuPage. RowsJson is a JSON array of arrays - one
/// positional array per row, the columns per feed as documented on getSkuPage.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSkuPageResponse
{
    boolean success;
    str errorCode;
    str message;
    str rowsJson;
    int rowCount;
    str nextKey;
    boolean hasMore;
    str serverUtc;
    str scope;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('RowsJson')]
public str parmRowsJson(str _value = rowsJson)
{
    rowsJson = _value;
    return rowsJson;
}

[DataMemberAttribute('RowCount')]
public int parmRowCount(int _value = rowCount)
{
    rowCount = _value;
    return rowCount;
}

[DataMemberAttribute('NextKey')]
public str parmNextKey(str _value = nextKey)
{
    nextKey = _value;
    return nextKey;
}

[DataMemberAttribute('HasMore')]
public boolean parmHasMore(boolean _value = hasMore)
{
    hasMore = _value;
    return hasMore;
}

/// <summary>
/// Which items the answer is for: '' every item, a warehouse its store's assortment. A device
/// whose cache is for another scope starts a full sync.
/// </summary>
[DataMemberAttribute('Scope')]
public str parmScope(str _value = scope)
{
    scope = _value;
    return scope;
}

[DataMemberAttribute('ServerUtc')]
public str parmServerUtc(str _value = serverUtc)
{
    serverUtc = _value;
    return serverUtc;
}
